        while (!dq.empty()) {
            int x = dq.front();
            dq.pop_front();
            int y = g[x];
            if (dis[y] > dis[x]) { // 传送花费 0
                dis[y] = dis[x];
                dq.push_front(y);
            }
            if (x < m && dis[x + 1] > dis[x] + 1) { // 右移花费 1
                dis[x + 1] = dis[x] + 1;
                dq.push_back(x + 1);
            }
        }
        cout << dis[m] << '\n';
    }
    return 0;
}
